42	/** Force-enables every family's real path at once — set only once ALL of them
43	 *  have been individually confirmed, not as a way to unblock just one. */
44	const REAL_APPLY_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1";
