87	export async function gameConfigApply(job: Job): Promise<void> {
88	  const serverId = job.serverId;
89	  if (!serverId) throw new Error("game config: job has no serverId");
90	
91	  const server = await db.server.findUnique({
92	    where: { id: serverId },
93	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
94	  });
95	  if (!server) throw new Error(`Server ${serverId} not found`);
96	
97	  const family = familyFor(server);
98	  const schema = schemaFor(family);
99	  if (!family || !schema) {
100	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
101	  }
102	
103	  const variant = server.gameVariant ?? schema.defaultVariant;
104	  const realApply = familyRealApplyEnabled(family);
105	
106	  // -------------------------------------------------------------------------
107	  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
108	  //
109	  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
110	  // customer request fell through to the block below, stamped an `_appliedAt`
111	  // marker, and notified them "Game settings applied on <hostname>" — with the
112	  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
113	  // customer changed their difficulty or slot count, was told it was applied, and
114	  // nothing on the server had changed.
115	  //
116	  // Identical in kind to the SSL bug fixed the same day, where production wrote a
117	  // certificate row as ACTIVE with an invented expiry while no certbot had run:
118	  // the system asserting an outcome it never performed. A change we did not apply
119	  // is a FAILURE, and it must say so loudly enough that an operator notices the
120	  // flag is missing.
121	  // -------------------------------------------------------------------------
122	  if (!realApply && !SANDBOX) {
123	    throw new Error(
124	      "Game settings could not be applied: real application is switched off on this " +
125	        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
126	        "server and your settings are NOT in effect. Please contact support."
127	    );
128	  }
129	
130	  if (!realApply) {
131	    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
132	    const marker = {
133	      _appliedVariant: variant,
134	      _appliedAt: new Date().toISOString(),
135	      _configVersion: GAME_CONFIG_VERSION,
136	      _sandbox: SANDBOX,
137	    };
138	
139	    await db.server.update({
140	      where: { id: server.id },
141	      data: { gameConfig: { ...existing, ...marker } as any },
142	    });
143	
144	    await notify(
145	      server.userId,
146	      `Game settings applied on ${server.hostname}`,
147	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
148	      `/dashboard/servers/${server.id}?tab=game settings`
149	    );
150	    return;
151	  }
152	
153	  // -------------------------------------------------------------------------
154	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
155	  // a failure notifies the user but never throws out of the handler.
156	  // -------------------------------------------------------------------------
157	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
158	  const valid = validateConfig(family, existing);
159	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
160	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
161	  const values = valid.ok ? valid.values : {};
162	
163	  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
164	  try {
165	    outcome = await applyRealConfig(server, family, values);
166	  } catch (e) {
167	    const msg = e instanceof Error ? e.message : String(e);
168	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
169	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
170	  }
171	
172	  // Always record the applied-marker (even on partial/soft failure) so the portal
173	  // reflects the attempt, and note whether the real push succeeded.
174	  const marker = {
175	    _appliedVariant: variant,
176	    _appliedAt: new Date().toISOString(),
177	    _configVersion: GAME_CONFIG_VERSION,
178	    _sandbox: SANDBOX,
179	    _real: true,
180	    _realOk: outcome.ok,
181	  };
182	  try {
183	    await db.server.update({
184	      where: { id: server.id },
185	      data: { gameConfig: { ...existing, ...marker } as any },
186	    });
187	  } catch (e) {
188	    console.error("[game-config] marker update failed", e);
189	  }
190	
191	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
192	  await notify(
193	    server.userId,
194	    outcome.ok
195	      ? `Game settings applied on ${server.hostname}`
196	      : `Game settings partially applied on ${server.hostname}`,
197	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
198	    `/dashboard/servers/${server.id}?tab=game settings`
199	  );
200	}
