209	/** The minimal Server shape the real path needs to open an SSH connection. */
210	export type SshServer = {
211	  id: string;
212	  rootPassword: string | null;
213	  rootPasswordEnc?: string | null;
214	  sshPort: number | null;
215	  dedicatedIp?: { address: string } | null;
