219	/**
220	 * Connect to the game-server VM (host/port derived exactly like the file manager,
221	 * user "root", password `rootPassword`), run `fn`, and always close the session.
222	 */
223	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
224	  return new Promise((resolve, reject) => {
225	    const target = connectionTarget(server as any);
226	    if (!target) {
227	      reject(new Error("server is not reachable yet — connection details are pending"));
228	      return;
229	    }
230	    const password = serverRootPassword(server);
231	    if (!password) {
232	      reject(new Error("server has no root password set"));
233	      return;
234	    }
235	
236	    const conn = new Client();
237	    let settled = false;
238	    const finish = (err: Error | null, val?: T) => {
239	      if (settled) return;
240	      settled = true;
241	      try {
242	        conn.end();
243	      } catch {
244	        /* best-effort */
245	      }
246	      if (err) reject(err);
247	      else resolve(val as T);
248	    };
249	
250	    conn.on("ready", () => {
251	      conn.sftp((err, sftp) => {
252	        if (err) return finish(err);
253	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
254	      });
255	    });
256	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
257	    conn.connect({
258	      host: target.host,
259	      port: target.port,
260	      username: "root",
261	      password,
262	      readyTimeout: CONNECT_TIMEOUT_MS,
263	    });
264	  });
265	}
