267	/** Read a remote text file, or null if it does not exist. */
268	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
269	  return new Promise((resolve, reject) => {
270	    sftp.readFile(path, (err, data) => {
271	      if (err) {
272	        // ENOENT / no such file → null; anything else is a real error.
273	        const code = (err as NodeJS.ErrnoException).code;
274	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
275	          return resolve(null);
276	        }
277	        return reject(err);
278	      }
279	      resolve(data.toString("utf8"));
280	    });
281	  });
282	}
283	
284	/** Write a remote text file (overwrites). */
285	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
286	  return new Promise((resolve, reject) => {
287	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
288	  });
289	}
