291	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
292	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
293	  return new Promise((resolve, reject) => {
294	    conn.exec(cmd, (err, stream: ClientChannel) => {
295	      if (err) return reject(err);
296	      let stdout = "";
297	      let stderr = "";
298	      const timer = setTimeout(() => {
299	        try {
300	          stream.close();
301	        } catch {
302	          /* ignore */
303	        }
304	      }, EXEC_TIMEOUT_MS);
305	      stream
306	        .on("close", (code: number) => {
307	          clearTimeout(timer);
308	          resolve({ code: code ?? 0, stdout, stderr });
309	        })
310	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
311	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
312	    });
313	  });
314	}
