316	/**
317	 * Locate the first existing path: try explicit candidates via `test -f`, then a
318	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
319	 * Non-destructive — only reads.
320	 */
321	async function remoteLocate(
322	  conn: Client,
323	  candidates: string[],
324	  findRoots: string[],
325	  findName: string
326	): Promise<string | null> {
327	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
328	  const findExpr = findRoots.length
329	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
330	    : "true";
331	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
332	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
333	  return hit ?? null;
334	}
