341	/** Dispatch to the correct family renderer. Exported for direct, real-server
342	 *  verification of a family's real-apply path (see REAL_APPLY_FAMILIES's own
343	 *  comment for what "confirmed" means) — not called externally otherwise. */
344	export async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
345	  return withSsh(server, async (conn, sftp) => {
346	    switch (family) {
347	      case "minecraft":
348	        return applyMinecraft(conn, sftp, values);
349	      case "rust":
350	        return applyRust(conn, sftp, values);
351	      case "valheim":
352	        return applyValheim(conn, sftp, values);
353	      case "cs2":
354	        return applyCs2(conn, sftp, values);
355	      case "palworld":
356	        return applyPalworld(conn, sftp, values);
357	      default:
358	        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
359	    }
360	  });
361	}
