366	
367	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
368	function updateKeyValue(content: string, updates: Record<string, string>): string {
369	  const lines = content.split(/\r?\n/);
370	  const seen = new Set<string>();
371	  for (let i = 0; i < lines.length; i++) {
372	    const trimmed = lines[i].trim();
373	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
374	    const eq = lines[i].indexOf("=");
375	    if (eq < 0) continue;
376	    const key = lines[i].slice(0, eq).trim();
377	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
378	      lines[i] = `${key}=${updates[key]}`;
379	      seen.add(key);
380	    }
381	  }
382	  for (const k of Object.keys(updates)) {
383	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
384	  }
385	  return lines.join("\n");
386	}
387	
388	/** Read a `key=value` file into a map (comments/blank lines ignored). */
389	function parseKeyValue(content: string): Record<string, string> {
390	  const out: Record<string, string> = {};
391	  for (const line of content.split(/\r?\n/)) {
392	    const t = line.trim();
393	    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
394	    const eq = line.indexOf("=");
395	    if (eq < 0) continue;
396	    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
397	  }
398	  return out;
399	}
