405	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
406	function updateConvars(content: string, updates: Record<string, string>): string {
407	  const lines = content.split(/\r?\n/);
408	  const seen = new Set<string>();
409	  for (let i = 0; i < lines.length; i++) {
410	    const t = lines[i].trim();
411	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
412	    const sp = t.search(/\s/);
413	    const key = sp < 0 ? t : t.slice(0, sp);
414	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
415	      lines[i] = `${key} ${updates[key]}`;
416	      seen.add(key);
417	    }
418	  }
419	  for (const k of Object.keys(updates)) {
420	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
421	  }
422	  return lines.join("\n");
423	}
