431	async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
432	  // TODO(paths): confirm the actual install dir/service name for the Minecraft
433	  // image. These candidates cover the common layouts; if none match we soft-fail
434	  // rather than create a stray server.properties in the wrong place.
435	  const path = await remoteLocate(
436	    conn,
437	    [
438	      "/opt/minecraft/server.properties",
439	      "/srv/minecraft/server.properties",
440	      "/home/minecraft/server.properties",
441	      "/minecraft/server.properties",
442	      "/root/minecraft/server.properties",
443	    ],
444	    ["/opt", "/srv", "/home"],
445	    "server.properties"
446	  );
447	  if (!path) {
448	    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
449	  }
450	
451	  const existing = await sftpRead(sftp, path);
452	  if (existing == null) {
453	    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
454	  }
455	
456	  // server.properties keys map 1:1 to the schema field keys.
457	  const updates: Record<string, string> = {};
458	  for (const [key, val] of Object.entries(v)) {
459	    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
460	  }
461	  const next = updateKeyValue(existing, updates);
462	  await sftpWrite(sftp, path, next);
463	
464	  const notes: string[] = [];
465	  // Best-effort live push via RCON for the live-editable fields; otherwise note a
466	  // restart. Wrapped so RCON problems never fail the apply.
467	  try {
468	    await tryMinecraftRcon(conn, next, v, notes);
469	  } catch (e) {
470	    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
471	    console.error("[game-config] minecraft rcon error", e);
472	  }
473	
474	  return {
475	    ok: true,
476	    applied: [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`],
477	    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
478	  };
479	}
