481	/**
482	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
483	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
484	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
485	 */
486	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
487	  const kv = parseKeyValue(props);
488	  const enabled = kv["enable-rcon"] === "true";
489	  const password = kv["rcon.password"] ?? "";
490	  // `rcon.port` is read out of the CUSTOMER'S OWN server.properties, on the
491	  // customer's own VM — an attacker-controlled string in every sense, and one
492	  // this platform never wrote. Only a TCP port number can ever be legitimate, so
493	  // anything that is not one is discarded rather than escaped. `shq` and the
494	  // quoting below are the second and third lines of defence; this is the first,
495	  // and it is the only one that does not depend on getting quoting right.
496	  const port = rconPort(kv["rcon.port"]);
497	  if (!enabled || !password) {
498	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
499	    return;
500	  }
501	  const which = await execRemote(conn, "command -v mcrcon || true");
502	  if (!which.stdout.trim()) {
503	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
504	    return;
505	  }
506	
507	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
508	  // runtime command set is verified for the target Minecraft build.
509	  const cmds: string[] = [];
510	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
511	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
512	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
513	  if (cmds.length === 0) return;
514	
515	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
516	  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
517	  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
518	  // is simply an unquoted, word-splitting, metacharacter-honouring shell
519	  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
520	  // customer's own server.properties ran as root on the hypervisor's SSH client
521	  // target with no further steps required.
522	  //
523	  // The `|| true` that used to end this line is gone. It forced exit 0, so the
524	  // `res.code === 0` test below was a constant and this function reported
525	  // "Pushed live settings via RCON." whether mcrcon worked, refused the
526	  // password, or was never reached. `execRemote` resolves with the real exit
527	  // code rather than rejecting, so nothing here can throw on a non-zero status —
528	  // the note just becomes true.
529	  const res = await execRemote(
530	    conn,
531	    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
532	  );
533	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
534	}
535	
536	/**
537	 * The RCON port to talk to, from an untrusted `rcon.port` value.
538	 *
539	 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
540	 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
541	 * Returns a string because it is interpolated into a command line, and returning
542	 * the parsed digits — never the caller's original text — is what makes the value
543	 * safe by construction rather than by escaping.
544	 */
545	function rconPort(raw: string | undefined): string {
546	  const n = Number(String(raw ?? "").trim());
547	  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
548	  return String(n);
549	}
550	
551	// ---------------------------------------------------------------------------
552	// Rust → server.cfg (server.<convar> value)
553	// ---------------------------------------------------------------------------
554	
555	async function applyRust(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
556	  // Rust reads server.cfg from <identity>/cfg/server.cfg — the identity dir is
557	  // deployment-specific, so we locate it rather than guessing.
558	  // TODO(paths): confirm the server identity/install path for the Rust image.
559	  const path = await remoteLocate(
560	    conn,
561	    ["/opt/rust/server/rustserver/cfg/server.cfg", "/opt/rust/server/cfg/server.cfg", "/home/rust/server/rustserver/cfg/server.cfg"],
562	    ["/opt/rust", "/home/rust", "/home/steam", "/opt"],
563	    "server.cfg"
564	  );
565	  if (!path) {
566	    return { ok: false, applied: [], notes: ["Could not locate Rust server.cfg — nothing was changed."] };
567	  }
568	  const existing = await sftpRead(sftp, path);
569	  if (existing == null) {
570	    return { ok: false, applied: [], notes: [`server.cfg disappeared at ${path} — nothing was changed.`] };
571	  }
572	
573	  // Field keys map to `server.<key>` convars; strings are quoted.
574	  const updates: Record<string, string> = {};
575	  for (const [key, val] of Object.entries(v)) {
576	    const convar = `server.${key}`;
577	    if (typeof val === "boolean") updates[convar] = bool(val);
578	    else if (typeof val === "number") updates[convar] = String(val);
579	    else updates[convar] = `"${String(val).replace(/"/g, '\\"')}"`;
580	  }
581	  const next = updateConvars(existing, updates);
582	  await sftpWrite(sftp, path, next);
583	
584	  // Rust RCON is a WebSocket (rcon.web) protocol — not attempted here.
585	  // TODO(rcon): push live convars (hostname/maxplayers/pve) via the Rust
586	  // WebSocket RCON if the server exposes it. For now note a restart/wipe.
587	  return {
588	    ok: true,
589	    applied: [`Wrote ${Object.keys(updates).length} convar(s) to ${path}.`],
590	    notes: ["Restart the server to apply. World-size/seed changes only take effect on the next map wipe."],
591	  };
592	}
