594	// ---------------------------------------------------------------------------
595	// Valheim → launch args (mechanism deployment-specific)
596	// ---------------------------------------------------------------------------
597	
598	async function applyValheim(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
599	  // Valheim settings are launch args (-world/-preset/-public/-password), not a
600	  // config file, so the exact wiring depends on the start script / systemd unit.
601	  // TODO(valheim): point the start script/systemd unit at the args file we write
602	  // below (or template the unit directly). We deliberately do NOT rewrite the
603	  // start script here — that would risk clobbering a script we can't parse.
604	  const parts: string[] = [];
605	  if (v["world"] != null) parts.push(`-world "${String(v["world"]).replace(/"/g, "")}"`);
606	  if (v["preset"] != null) parts.push(`-preset ${String(v["preset"])}`);
607	  if (v["public"] != null) parts.push(`-public ${bool(v["public"]) === "true" ? "1" : "0"}`);
608	  if (v["password"] != null && String(v["password"]).length > 0) {
609	    parts.push(`-password "${String(v["password"]).replace(/"/g, "")}"`);
610	  }
611	  const args = parts.join(" ");
612	
613	  // Find a Valheim install dir to drop the args file next to.
614	  const dir = await remoteLocate(
615	    conn,
616	    [],
617	    ["/opt/valheim", "/home/valheim", "/home/steam/valheim", "/opt"],
618	    "valheim_server.x86_64"
619	  );
620	  if (!dir) {
621	    return {
622	      ok: false,
623	      applied: [],
624	      notes: ["Could not locate the Valheim install — launch args were not written. Restart with the new args once the install path is known."],
625	    };
626	  }
627	  const targetDir = dir.replace(/\/[^/]*$/, "");
628	  const argsFile = `${targetDir}/nxeon-launch-args.txt`;
629	  await sftpWrite(sftp, argsFile, args + "\n");
630	
631	  return {
632	    ok: true,
633	    applied: [`Wrote launch args to ${argsFile}.`],
634	    notes: ["Wire the start script/systemd unit to source this file, then restart the server. Password/world changes require a restart."],
635	  };
636	}
637	
638	// ---------------------------------------------------------------------------
639	// CS2 → server.cfg (cvars) + launch-only notes
640	// ---------------------------------------------------------------------------
641	
642	const CS2_GAME_MODE: Record<string, { game_type: string; game_mode: string }> = {
643	  competitive: { game_type: "0", game_mode: "1" },
644	  wingman: { game_type: "0", game_mode: "2" },
645	  casual: { game_type: "0", game_mode: "0" },
646	  deathmatch: { game_type: "1", game_mode: "2" },
647	  custom: { game_type: "3", game_mode: "0" },
648	};
649	
650	async function applyCs2(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
651	  // TODO(paths): confirm the CS2 dedicated-server cfg dir (…/game/csgo/cfg).
652	  const path = await remoteLocate(
653	    conn,
654	    [
655	      "/opt/cs2/game/csgo/cfg/server.cfg",
656	      "/home/cs2/cs2/game/csgo/cfg/server.cfg",
657	      "/home/steam/cs2/game/csgo/cfg/server.cfg",
658	    ],
659	    ["/opt/cs2", "/home/cs2", "/home/steam", "/opt"],
660	    "server.cfg"
661	  );
662	  if (!path) {
663	    return { ok: false, applied: [], notes: ["Could not locate CS2 server.cfg — nothing was changed."] };
664	  }
665	  const existing = await sftpRead(sftp, path);
666	  if (existing == null) {
667	    return { ok: false, applied: [], notes: [`server.cfg disappeared at ${path} — nothing was changed.`] };
668	  }
669	
670	  const updates: Record<string, string> = {};
671	  const notes: string[] = [];
672	
673	  if (v["maxrounds"] != null) updates["mp_maxrounds"] = String(v["maxrounds"]);
674	  if (v["bots"] != null) updates["bot_quota"] = bool(v["bots"]) === "true" ? "10" : "0";
675	  if (v["game_mode"] != null) {
676	    const gm = CS2_GAME_MODE[String(v["game_mode"])];
677	    if (gm) {
678	      updates["game_type"] = gm.game_type;
679	      updates["game_mode"] = gm.game_mode;
680	      notes.push("game_type/game_mode take effect on next map load / relaunch.");
681	    }
682	  }
683	  if (v["tickrate"] != null) {
684	    // -tickrate is a launch parameter, not a cvar — cannot be set from server.cfg.
685	    notes.push(`Tickrate ${String(v["tickrate"])} requires relaunching CS2 with -tickrate ${String(v["tickrate"])}.`);
686	  }
687	
688	  const next = updateConvars(existing, updates);
689	  await sftpWrite(sftp, path, next);
690	
691	  // TODO(rcon): CS2 supports source RCON — mp_maxrounds/bot_quota could be pushed
692	  // live if the rcon_password is known. Not attempted here (credentials unknown).
693	  return {
694	    ok: true,
695	    applied: [`Wrote ${Object.keys(updates).length} cvar(s) to ${path}.`],
696	    notes: notes.length ? notes : ["Reload the map or exec server.cfg for the new cvars to take effect."],
697	  };
698	}
699	
700	// ---------------------------------------------------------------------------
701	// Palworld → container recreation with an --env-file (NOT direct ini editing)
702	//
703	// Found live 2026-09-05 (customer ticket: their hand-edits to
704	// PalWorldSettings.ini kept reverting): the `thijsvanloef/palworld-server-docker`
705	// image's `start.sh` unconditionally regenerates PalWorldSettings.ini from its
706	// own environment variables on EVERY container boot — the file is generated
707	// output, never a source of truth. The previous version of this function wrote
708	// settings directly into that ini via SFTP, which is the EXACT bug the
709	// customer hit: correct-looking on write, silently wiped the next time the
710	// container restarts for any reason (crash, host reboot, a future settings
711	// change). It was never live in production (ENABLE_REAL_GAMECFG was off), so
712	// no customer was ever bitten by it, but turning the flag on without fixing
713	// this first would have shipped that same bug to everyone.
714	//
715	// The only durable way to change these settings is to recreate the container
716	// with updated environment variables. Secrets (ADMIN_PASSWORD, which also
717	// gates RCON) are written to an --env-file over SFTP and referenced by path —
718	// never passed as `-e KEY=value` on a command line, where they would sit in
719	// plaintext in `ps aux`/shell history on the customer's own VM (the same
720	// hardening already applied by hand to sausaugepro's live fix the same day).
721	// Uses the exact fixed flags prisma/catalog.ts's Palworld template provisions
722	// with — this function is already Palworld-specific, so it can assume them
723	// rather than rediscovering a container it will recreate anyway.
724	// ---------------------------------------------------------------------------
725	
726	const PALWORLD_CONTAINER = "palworld";
727	
728	/** Schema field key → Palworld env var name + how to format the value. */
729	const PALWORLD_ENV_MAP: Record<string, { env: string; format: (v: string | number | boolean) => string }> = {
730	  difficulty: { env: "DIFFICULTY", format: (v) => String(v) },
731	  "death-penalty": { env: "DEATH_PENALTY", format: (v) => String(v) },
732	  pvp: { env: "IS_PVP", format: (v) => (bool(v) === "true" ? "True" : "False") },
733	  "exp-rate": {
734	    env: "EXP_RATE",
735	    format: (v) => {
736	      const n = Number(v);
737	      return Number.isFinite(n) ? n.toFixed(6) : String(v);
738	    },
739	  },
740	  "player-caps": { env: "PLAYERS", format: (v) => String(v) },
741	  "pal-box-import": { env: "ALLOW_GLOBAL_PALBOX_IMPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
742	  "pal-box-export": { env: "ALLOW_GLOBAL_PALBOX_EXPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
743	  // The image's own official escape hatch (see start.sh): when true, boot skips
744	  // regenerating PalWorldSettings.ini entirely (only copies a default template
745	  // if the file is completely empty) — the only way to give a customer a
746	  // config file that genuinely survives restarts. Found live 2026-09-05.
747	  "raw-config-mode": { env: "DISABLE_GENERATE_SETTINGS", format: (v) => (bool(v) === "true" ? "True" : "False") },
748	};
749	
750	async function applyPalworld(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
751	  const inspect = await execRemote(conn, `docker inspect ${PALWORLD_CONTAINER} --format '{{json .Config.Env}}'`);
752	  if (inspect.code !== 0) {
753	    return { ok: false, applied: [], notes: [`Could not find the "${PALWORLD_CONTAINER}" container — nothing was changed.`] };
754	  }
755	  let envArr: string[];
756	  try {
757	    envArr = JSON.parse(inspect.stdout.trim());
758	  } catch {
759	    return { ok: false, applied: [], notes: ["Could not read the server's current settings — nothing was changed."] };
760	  }
761	  const envMap = new Map<string, string>();
762	  for (const entry of envArr) {
763	    const idx = entry.indexOf("=");
764	    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
765	  }
766	  envMap.delete("PATH"); // always injected correctly by the image itself
767	
768	  const applied: string[] = [];
769	  for (const [key, val] of Object.entries(v)) {
770	    const mapping = PALWORLD_ENV_MAP[key];
771	    if (!mapping || val == null) continue;
772	    envMap.set(mapping.env, mapping.format(val));
773	    applied.push(key);
774	  }
775	  if (applied.length === 0) {
776	    return { ok: true, applied: [], notes: ["No changes to apply."] };
777	  }
778	
779	  const envFileContent = Array.from(envMap.entries()).map(([k, val]) => `${k}=${val.replace(/\r?\n/g, " ")}`).join("\n") + "\n";
780	  await sftpWrite(sftp, "/root/palworld.env", envFileContent);
781	  await execRemote(conn, "chmod 600 /root/palworld.env");
782	
783	  // Disable the restart policy BEFORE stopping — found live 2026-09-05: `docker
784	  // stop` on a container with `--restart unless-stopped` has a real race window
785	  // where the policy can bring it back up before the follow-on `rename`/`run`
786	  // complete, silently reviving the OLD (about-to-be-replaced) container mid-
787	  // sequence. Observed corrupting a raw-config-mode customer's manually-edited
788	  // settings once. Turning the policy off first, while it's still running,
789	  // closes the race entirely rather than racing a stop.
790	  const prep = await execRemote(
791	    conn,
792	    `docker update --restart=no ${PALWORLD_CONTAINER} 2>/dev/null; docker rm -f ${PALWORLD_CONTAINER}-old 2>/dev/null; docker stop ${PALWORLD_CONTAINER} && docker rename ${PALWORLD_CONTAINER} ${PALWORLD_CONTAINER}-old`
793	  );
794	  if (prep.code !== 0) {
795	    return { ok: false, applied: [], notes: [`Could not stop the running server to apply changes: ${prep.stderr || prep.stdout}`] };
796	  }
797	
798	  const run = await execRemote(
799	    conn,
800	    `docker run -d --name ${PALWORLD_CONTAINER} -p 8211:8211/udp -p 127.0.0.1:25575:25575/tcp -v /opt/palworld:/palworld --restart unless-stopped --env-file /root/palworld.env thijsvanloef/palworld-server-docker`
801	  );
802	  if (run.code !== 0) {
803	    // Roll back — the customer's server must not end up worse off than before.
804	    await execRemote(conn, `docker rm -f ${PALWORLD_CONTAINER} 2>/dev/null; docker rename ${PALWORLD_CONTAINER}-old ${PALWORLD_CONTAINER} && docker start ${PALWORLD_CONTAINER}`);
805	    return { ok: false, applied: [], notes: [`Failed to apply — rolled back to the previous working configuration: ${run.stderr || run.stdout}`] };
806	  }
807	  await execRemote(conn, `docker rm ${PALWORLD_CONTAINER}-old`);
808	
809	  return {
810	    ok: true,
811	    applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`],
812	    notes: ["Your server restarted briefly to apply these — any connected players were disconnected and can rejoin now."],
813	  };
814	}
