async function provision(job: Job) {
  const server = await loadServer(job);
  // Clear any stale failure reason from a previous attempt as this run starts, so
  // a successful retry doesn't leave the last error hanging around on the row.
  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null, provisioningStep: null } });
  // Best-effort, human-readable "what's happening right now" label for
  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
  // SSH reachability, and the game's own port opening). Never allowed to fail
  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
  // equivalent `step()`.
  const step = (label: string) =>
    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);

  if (SANDBOX) {
    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
    const vmid = server.vmid ?? (990000 + (await db.server.count()));
    const password = generatePassword();
    const ip = sandboxIp(vmid);
    await db.server.update({
      where: { id: server.id },
      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
    });
    await notify(
      server.userId,
      `Server ${server.hostname} is ready`,
      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
      `/dashboard/servers/${server.id}`
    );
    // Post-purchase review request (once per server, skipped if no profiles set).
    await sendReviewRequestForServer(server.id);
    return;
  }

  const { conn, row: nodeRow } = await nodeFor(server);
  const storage = server.plan.storageTier === "hdd"
    ? nodeRow?.storageHdd ?? "vmdata-hdd"
    : nodeRow?.storageNvme ?? "vmdata";

  // Pick a vmid that does NOT still own a previous tenant's backup archives.
  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
  // server's vzdump archives, so the id freed by a deletion comes back carrying
  // the old owner's backups — which every backup surface then attributes to the
  // new customer (listBackups/requestRestore key on vmid alone). See
  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
  // keeps the vmid already persisted on the row.
  // The primary's real backup-archive storage predates the storageHdd naming
  // convention (it's literally "backup", not "vmdata-hdd") — every node
  // onboarded since names its backup-content storage after storageHdd instead.
  // See archivedVmids' doc comment in lib/proxmox.ts for the full story.
  const backupStorage = nodeRow?.isPrimary ? "backup" : (nodeRow?.storageHdd ?? "backup");
  const vmid = server.vmid ?? (await allocateFreshVmid(conn, backupStorage));

  // The password must be generated ONCE per VM, not once per attempt. cloud-init's
  // cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
  // cipassword was baked into the FIRST boot's snippet and never re-applies on a
  // later config change unless the guest gets a brand-new instance-id. A retried
  // PROVISION (server.vmid already set = the clone below is skipped as
  // `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
  // again anyway and overwrite Server.rootPasswordEnc with a value the running VM
  // never saw — every later SSH from the platform (control panel, GAME_POWER,
  // mods, backups) then authenticated with a password that does not match
  // /etc/shadow on the guest, failing with "All configured authentication methods
  // failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
  // logins ever, until the guest's password was force-resynced via the QGA
  // set-user-password path). Reuse the already-stored password whenever this
  // server already has a vmid (meaning some earlier attempt may have already
  // cloned + booted it); only a truly first attempt mints a new one.
  const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();

  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
  // VPS: the global `dedicated_ip_default` setting acts as a platform-wide default (included
  // on every plan unless the admin switches it off). Game servers: the customer must
  // explicitly purchase the addon at checkout — game orders set `wantsDedicatedIp` from the
  // intent, so the global default must NOT override it (that was silently granting free IPs).
  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
  const { getSettingBool: _settingBool } = await import("../lib/settings");
  const isGame = !!server.gamePlanId;
  const wantDedicated = isGame
    ? server.wantsDedicatedIp
    : server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
  if (wantDedicated && (await dedicatedIpProviderConfigured(nodeRow?.id))) {
    try {
      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
      // server's already-ASSIGNED IP rather than claiming a second pool IP.
      // nodeRow is THIS server's own node — a Hetzner-hosted server draws from
      // the Hetzner pool, not whichever pool happens to be configured (the bug
      // this replaces: the old `ovhConfigured()`-only gate had no node
      // awareness at all).
      dedicated = await allocateDedicatedIp(server.id, vmid, nodeRow?.id);
    } catch (e) {
      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
    }
  }
  // Node-aware + transactionally-claimed allocation (passing the server id enables
  // the claim path, so two concurrent provisions can't pick the same IP/port).
  let ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
  let sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));

  try {
    await db.server.update({
      where: { id: server.id },
      data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
    });
  } catch (e: any) {
    // Defense in depth: `Server.ipAddress` is UNIQUE and shared between dedicated
    // and NAT addresses, so any future desync between the DedicatedIp pool and
    // this column (the class of bug fixed in releaseDedicatedIp — see its
    // comment) would otherwise crash-loop identically on every PROVISION retry,
    // since cleanupFailedProvision() just re-frees the same stuck pool row. If
    // we were the one claiming a dedicated IP, self-heal: null it off whichever
    // stale server row is still squatting on it, release our own bad claim, and
    // fall back to NAT so this customer's server still deploys.
    if (dedicated && e?.code === "P2002") {
      console.error(`[worker] dedicated IP ${dedicated.address} collided with a stale Server.ipAddress — self-healing and falling back to NAT`, e);
      await db.server.updateMany({ where: { ipAddress: dedicated.address }, data: { ipAddress: null, ipv6: null } });
      await releaseDedicatedIp(server.id).catch(() => {});
      dedicated = null;
      ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
      sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
      await db.server.update({
        where: { id: server.id },
        data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
      });
    } else {
      throw e;
    }
  }

  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
  // (worker restart mid-clone, or any transient failure in the steps below) would
  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
  // the clone is idempotent, so skip it when the VM is already present.
  let vmAlreadyExists = false;
  try {
    await conn.vmStatus(vmid);
    vmAlreadyExists = true;
  } catch {
    vmAlreadyExists = false;
  }
  if (vmAlreadyExists) {
    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
  } else {
    await step("Allocating your server…");
    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
      newid: vmid,
      name: server.hostname,
      full: 1,
      storage,
    });
    await conn.waitForTask(cloneUpid, 600_000);
  }

  // Per-server cloud-init snippet (base + panel/app install + add-ons).
  //
  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
  // failed write hands the VM a vendor-data file that does not exist. Root SSH
  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
  // all silently vanish, and the customer is still told the server is ready.
  // Failing here is recoverable — the job retries, and the clone above is
  // idempotent. Continuing is not.
  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
  // generate its one-time admin password (persisted, once) and get the idempotent
  // install script to bake into cloud-init. Null for an ordinary VPS.
  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
  // Live telemetry: mint a fresh per-server shipper token and persist its hash
  // BEFORE building cloud-init, so the config the agent boots with matches what
  // the ingest route will look up (lib/telemetry-token.ts). Re-provisioning
  // (this code path runs again) simply mints a new token, invalidating the old
  // one — no rotation UI needed for that case.
  (server as any).__telemetryToken = await mintServerTelemetryToken(server.id);

  await step("Configuring the network…");
  // The vendor snippet must land on THIS SERVER'S OWN NODE's filesystem, but
  // there is exactly one worker process for the whole platform and it runs
  // only on the primary — it has no local filesystem access to a different
  // physical node at all. The primary writes its own snippet directly
  // (SNIPPET_DIR); a non-primary node's snippet is written remotely through
  // its own node-agent (Phase 3 of the 2026-09-05 multi-node hardening plan —
  // see docs/DOCUMENTATION.md's "Multi-node synergy" section) using that
  // node's own snippet-capable storage (isPrimary ? "backup" : storageHdd —
  // the same divergence fixed for backups the same day). If the agent isn't
  // configured yet for that node (no token set, e.g. a node onboarded before
  // Phase 3 shipped, or before its agent step was run), this DEGRADES rather
  // than hard-fails: native cloud-init (root password + SSH keys below)
  // still works fully since it's a Proxmox cfg field, not file-based, so the
  // customer gets a normal, SSH-reachable server — just without the vendor
  // extras (Claude Code pre-install, Docker/ClamAV add-ons, the game/app
  // setup script, MOTD) until the agent is set up for that node. Never
  // silently reference a snippet file that was never written — that is the
  // exact prior incident this function still guards against for the
  // primary's own local write below.
  const snippetStorage = nodeRow?.isPrimary ? SNIPPET_STORAGE : (nodeRow?.storageHdd ?? SNIPPET_STORAGE);
  const snippetFilename = `nxeon-${vmid}.yaml`;
  let cicustom: string | undefined;
  if (nodeRow?.isPrimary ?? true) {
    const snippet = buildCloudInit(server);
    try {
      await writeFile(`${SNIPPET_DIR}/${snippetFilename}`, snippet, "utf8");
    } catch (e: any) {
      throw new Error(
        `could not write the cloud-init snippet ${SNIPPET_DIR}/${snippetFilename} (${e?.message ?? e}). ` +
          `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
          `stopped here rather than reporting a server that would not be usable.`
      );
    }
    cicustom = `vendor=${snippetStorage}:snippets/${snippetFilename}`;
  } else if (nodeRow) {
    const snippet = buildCloudInit(server);
    try {
      await agentWriteSnippet(nodeRow, snippetStorage, snippetFilename, snippet);
      cicustom = `vendor=${snippetStorage}:snippets/${snippetFilename}`;
      console.log(`[worker] wrote a fresh per-VM cloud-init snippet for ${server.id} via node-agent on ${nodeRow.name}`);
    } catch (e: any) {
      // Correction (found live, same day this degraded path was first built):
      // on this fallback, DO NOT delete/override cicustom. `qm clone` already
      // copied the TEMPLATE's own cicustom onto this VM, and that static
      // "nxeon-vendor.yaml" (scripts/onboard-node.sh step 4, present on every
      // onboarded node) is NOT just cosmetic — it sets `ssh_pwauth: true` plus
      // a sshd_config drop-in enabling PasswordAuthentication, and `systemctl
      // enable --now qemu-guest-agent`. Proxmox's native `cipassword` field
      // alone does NOT enable password auth on a stock cloud image (it ships
      // with PasswordAuthentication no) — deleting cicustom, as an earlier
      // version of this fix did, left the guest with NO way to accept the
      // root password at all AND no guest-agent startup, confirmed live by a
      // real provision hanging forever on node-2. Leaving cicustom untouched
      // means the guest still gets ssh_pwauth + guest-agent from the
      // template's own (correctly node-scoped) snippet — just not the per-VM
      // extras — whenever the agent call itself fails for any reason.
      console.warn(
        `[worker] provisioning ${server.id} on non-primary node ${nodeRow.name} — node-agent snippet write ` +
          `failed (${e instanceof NodeAgentError ? e.message : String(e?.message ?? e)}), keeping the template's ` +
          `static vendor snippet (ssh_pwauth + guest-agent startup) instead; the game/app setup script, Claude ` +
          `Code, and other add-ons are skipped for this provision.`
      );
    }
  } else {
    console.warn(
      `[worker] provisioning ${server.id} with no resolved node row — keeping the template's static vendor ` +
        `snippet instead of a fresh per-VM one; the game/app setup script, Claude Code, and other add-ons are ` +
        `skipped for this provision.`
    );

  );
}

const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
const sshkeys = keys.length
  ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
  : undefined;
const cfg: Record<string, any> = {
  cores: server.plan.cpuCores,
  memory: server.plan.ramMB,
  ciuser: "root",
  cipassword: password,
  sshkeys,
  nameserver: "1.1.1.1 8.8.8.8",
  onboot: 1,
  // Omit cicustom (rather than deleting it) when there's no fresh per-VM
  // snippet to point it at — see the long comment above ("Configuring the
  // network…") for why the template's own inherited value must survive
  // here, not be cleared. It only works correctly because every onboarded
  // node's templates have a valid, node-scoped storage reference for it
  // (fixed 2026-09-05 after the templates migrated from primary carried the
  // wrong storage name).
  ...(cicustom ? { cicustom } : {}),
  tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
};
if (dedicated) {
  // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
  cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
  cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
} else {
  // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
  cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
}
await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);

// Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
// customer bought as a deploy-time upsell, so the VM is born the right size and
// no separate DISK_EXPAND job is needed on a fresh order.
await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
  disk: "scsi0",
  size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
});

// Port forwarding is what makes the `ssh root@host -p <port>` line below true
// for a NAT server. If it cannot be proved, the readiness message says so
// instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
// VM itself is fine and a failed PROVISION would flip it to ERROR and release
// its IP, which is a worse outcome than a missing forward.
let natError: Error | null = null;
if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);

// Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
// AFTER the VM was already created and started; the reaper then re-queues the job.
// Starting an already-running VM makes Proxmox's start task fail with "already
// running", which — before this guard — stranded a perfectly good, reachable VM in
// ERROR forever (every retry hit the same wall). So skip the start when the VM is
// already running, and treat an "already running" race as success rather than fatal.
const alreadyRunning = await conn
  .vmStatus(vmid)
  .then((s: { status?: string } | null) => s?.status === "running")
  .catch(() => false);
if (!alreadyRunning) {
  await step("Starting your server…");
  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  try {
    await conn.waitForTask(startUpid);
  } catch (e) {
    if (!/already running/i.test(String((e as { message?: unknown })?.message ?? ""))) throw e;
  }
}

// `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
// agent whether the machine actually booted before calling it ready (M7 #10).
// A false here is reported, never downgraded into silence.
if (!SANDBOX) await step("Booting the operating system…");
const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);

// Real end-to-end reachability check — the guest agent above proves only that
// QEMU's in-guest daemon answered (and plenty of images don't even ship it, see
// the `booted` caveat below). Neither that nor `waitForTask` proves a customer
// can actually reach the thing we are about to call "ready". Two real incidents
// shipped without this: a VM whose IP collided with unrelated infrastructure
// (nothing was ever reachable), and separately every game family's
// `docker run -d` setup script creates no systemd unit, so the game process can
// silently fail to start while the container still shows "Up" (confirmed:
// Terraria hung on an interactive world-selection prompt with no TTY, port
// never bound) — PROVISION reported success both times. This throws on
// failure, same as every other fatal step above: the existing `runJob` catch
// path (retry while attempts remain, else ERROR + release the dedicated IP +
// `notifyProvisionFailed`) handles it, and because this runs BEFORE the
// status flip to RUNNING and the deployment email below, neither ever fires
// for a server that failed this check.
if (!SANDBOX) {
  // Same address a customer would use: the dedicated IP if one was allocated,
  // else the NAT host's public IP + this server's assigned SSH port — reusing
  // `dedicated`/`sshPort` computed earlier rather than recomputing them (see
  // the identical `sshLine` construction below).
  const sshHost = dedicated ? dedicated.address : (server.node?.publicIp ?? process.env.PUBLIC_IP);
  const sshCheckPort = dedicated ? 22 : (sshPort ?? 22);
  await step("Waiting for network access…");
  const ssh = await checkSshReachable(sshHost!, sshCheckPort);
  if (!ssh.ok) {
    throw new Error(
      `SSH did not respond on ${sshHost}:${sshCheckPort} after ~${Math.round(ssh.elapsedMs / 1000)}s ` +
        `(${ssh.attempts} attempt(s); last error: ${ssh.error}). The VM started, but nothing answered SSH, ` +
        `so this server cannot be handed to the customer as ready.`
    );
  }

  const game = gamePortForServer(server as unknown as ServerFamilyLike);
  if (game) {
    // The one genuinely game-specific checkpoint: the guest is up and SSH
    // answers, but the game process itself may still be pulling its image and
    // starting its container before its own port opens — a real, observable
    // distinction (not present at all for a plain VPS order), unlike "pulling
    // the image" itself, which happens inside the guest's own cloud-init run
    // with no channel back to this worker to report on.
    await step("Starting the game server…");

    // `ip` (the guest's own private address) only works as a check target on
    // the PRIMARY: the worker always runs there, sharing that node's own
    // bridge network, so a direct connect to 10.20.0.x succeeds. Any OTHER
    // node is a separate NAT island by design (see the multi-node docs) —
    // the primary has NO route to a non-primary node's private subnet at
    // all, so checking `ip` directly there fails with EHOSTUNREACH 100% of
    // the time, regardless of whether the game server is healthy. Found
    // live: the very first real customer ever freshly provisioned onto
    // node-2 hit this unconditionally — SSH passed (it already correctly
    // checks the public address), the game-port check could not, ever.
    // Fix: for a NAT (non-dedicated) server on a non-primary node, forward
    // the port FIRST (reusing an existing forward on retry rather than
    // allocating a new public port every attempt) and check through it via
    // the node's own public IP — the exact same external path a real
    // customer uses, already proven to work by the SSH check just above.
    let checkHost = ip;
    let checkPort = game.port;
    if (!SANDBOX && !dedicated && !nodeRow?.isPrimary) {
      const existing = await db.portForward.findFirst({
        where: { serverId: server.id, guestPort: game.port, protocol: game.protocol },
        select: { publicPort: true },
      });
      checkPort = existing?.publicPort ?? (await allocateGameForward(server.nodeId, server.id, game.port, game.protocol));
      const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
      if (natErr) {
        throw new Error(
          `could not sync the game port forward on ${nodeRow?.name ?? "the target node"} for verification: ${natErr}`
        );
      }
      checkHost = server.node?.publicIp ?? process.env.PUBLIC_IP ?? ip;
    }

    const gameCheck = await checkGamePortOpen(checkHost, checkPort, game.protocol);
    if (!gameCheck.ok) {
      throw new Error(
        `game port ${game.port}/${game.protocol} never opened on ${checkHost}:${checkPort} after ` +
          `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
          `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
          `server cannot be handed to the customer as ready.`
      );
    }
    // Auto-forward the game's own port for NAT (non-dedicated-IP) servers ON
    // THE PRIMARY — non-primary nodes already forwarded it above, since that
    // was the only way to even perform the check. "Plug and play": every
    // game server is reachable the moment it's handed to the customer
    // instead of requiring a manual PortForward from the dashboard first.
    // Found live: a real paying Minecraft customer with no dedicated IP and
    // zero forwards had no path from any public IP to their game port at
    // all. Dedicated IP servers need no forward — their guest port already
    // IS the public port.
    if (!SANDBOX && !dedicated && nodeRow?.isPrimary) {
      try {
        await allocateGameForward(server.nodeId, server.id, game.port, game.protocol);
        const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
        if (natErr) console.error(`[worker] game port forward sync failed for ${server.hostname}`, natErr);
      } catch (e) {
        // Never fail the whole provision over this — the server is still usable
        // via the dashboard's existing manual "Add forward" as a fallback.
        console.error(`[worker] auto-forward game port failed for ${server.hostname}`, e);
      }
    }
    // Minecraft subdomain DNS (lib/game-subdomain-dns.ts): the game port is
    // now reachable either way (dedicated IP directly, or the forward just
    // created above), so this can fire unconditionally.
    if (server.subdomain) {
      await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
    }
  } else if (server.gamePlanId) {
    // A game order whose family we could not map to a port (new game added to
    // GAME_FAMILIES/catalog without a matching lib/games.ts GAME_PORT entry).
    // This is a config gap, not evidence the server is unhealthy — log it
    // loudly for whoever ships the next game, but do not fail a customer's
    // order over our own missing map entry.
    console.error(
      `[worker] provision ${server.hostname}: game order (gamePlanId=${server.gamePlanId}, ` +
        `osTemplate.family=${server.osTemplate?.family ?? "?"}) has no GAME_PORT entry — skipped the game-port check`
    );
  }
}

const runningServer = await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", provisioningStep: null } });

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
import {
  controlSpec,
  isGameFamily,
  isPowerAction,
  remoteLocateDir,
  runRcon,
  parsePlayers,
  computeNextRun,
  computeNextIntervalRun,
  shq,
  isSafeRemotePath,
  GAME_BACKUP_DIR,
  type GameControlSpec,
} from "../lib/game-control";
import type { Job } from "@prisma/client";

/**
 * Game server control-panel worker handlers.
 *
 * Registered in worker/index.ts:
 *   GAME_POWER:  gamePower,
 *   GAME_BACKUP: gameBackup,
 * and `gameScheduleSweep()` called on a ~60s timer.
 *
 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
 * and the root password is never surfaced in an error (only a trimmed remote stderr
 * is, which never contains it).
 *
 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
 */

const CONTROL_FIELDS = {
  id: true,
  userId: true,
  hostname: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
  node: { select: { publicIp: true } },
  osTemplate: { select: { family: true } },
  gamePlan: { select: { gameFamily: true } },
} as const;

type ControlServer = {
  id: string;
  userId: string;
  hostname: string;
  status: string;
  rootPassword: string | null;
  rootPasswordEnc: string | null;
  sshPort: number | null;
  dedicatedIp: { address: string } | null;
  node: { publicIp: string } | null;
  osTemplate: { family: string | null };
  gamePlan: { gameFamily: string | null } | null;
};

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-control] notify failed", e);
  }
}

function resolveSpec(server: ControlServer): GameControlSpec {
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (!isGameFamily(fam)) throw new Error("not a game server");
  const spec = controlSpec(fam);
  if (!spec) throw new Error("no control spec for family");
  return spec;
}

/**
 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
 * the family's control spec (compile-time constants); `action` is one of the three
 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
 * a successful action (the same discipline as worker/game-update.ts).
 */
function powerScript(spec: GameControlSpec, action: string): string {
  const hints = spec.serviceHints.map(shq).join(" ");
  return [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
    `echo "NXGP:UNIT:$unit"`,
    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
    `echo "NXGP:END"`,
  ].join("\n");
}

/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
export async function gamePower(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);

  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
  const action = String(p.action ?? "");
  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );

