 * Sweep harness: delete a throwaway test server's DB rows COMPLETELY.
 * Refuses to touch anything that isn't one of this sweep's own servers
 * (ops user + hostname prefix "t-"), so it can never hit a real customer row.
 * Usage: npx tsx teardown-db.ts <serverId>
 */
import { db } from "/opt/nxeon/lib/db";

const OPS_USER = "cmrztujaw0002hlazl58i3lsi";

(async () => {
  const serverId = process.argv[2];
  if (!serverId) throw new Error("usage: teardown-db.ts <serverId>");
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, hostname: true, userId: true, vmid: true, nodeId: true },
  });
  if (!s) {
    console.log(JSON.stringify({ serverId, result: "already-gone" }));
    await db.$disconnect();
    return;
  }
  // Hard safety gate — this sweep only ever created rows shaped like this.
  if (s.userId !== OPS_USER || !/^t-[a-z0-9]+-[a-z0-9]+$/.test(s.hostname)) {
    throw new Error(
      `REFUSING to delete ${s.id} (${s.hostname}): not a sweep-created throwaway server`
    );
  }

  const pf = await db.portForward.deleteMany({ where: { serverId } });
  const jobs = await db.job.deleteMany({ where: { serverId } });
  // Anything else that could hold an FK to Server — delete defensively but only
  // for this row. Unknown models are skipped silently.
  for (const model of [
    "backup",
    "serverMetric",
    "gameSchedule",
    "notification",
  ] as const) {
    try {
      // @ts-expect-error dynamic model access, guarded by try/catch
      await db[model].deleteMany({ where: { serverId } });
    } catch {
      /* model doesn't exist or has no serverId — fine */
    }
  }
  await db.server.delete({ where: { id: serverId } });
  console.log(
    JSON.stringify({ serverId, hostname: s.hostname, vmid: s.vmid, deletedForwards: pf.count, deletedJobs: jobs.count, result: "deleted" })
  );
  await db.$disconnect();
})().catch((e) => {
  console.error(String(e?.message ?? e));
  process.exit(1);
});

