/**
 * Sweep harness: call worker/game-config.ts's applyRealConfig() DIRECTLY against a
 * real running test server, exactly the way the 2026-09-06 minecraft verification
 * did. Prints the ApplyOutcome. Read the resulting config file back off disk via
 * SSH afterwards — this script proves nothing on its own.
 *
 * Usage: npx tsx apply.ts <serverId> '<json values>'
 *   e.g. npx tsx apply.ts cmxxx '{"difficulty":"hard","online-mode":false}'
 */
import { db } from "/opt/nxeon/lib/db";
import { applyRealConfig } from "/opt/nxeon/worker/game-config";

(async () => {
  const serverId = process.argv[2];
  const valuesRaw = process.argv[3] ?? "{}";
  if (!serverId) throw new Error("usage: apply.ts <serverId> '<json values>'");
  const values = JSON.parse(valuesRaw);

  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      hostname: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
      gamePlan: { select: { gameFamily: true } },
      osTemplate: { select: { family: true } },
    },
  });
  if (!s) throw new Error(`server ${serverId} not found`);
  const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family;
  if (!family) throw new Error("not a game server");

  console.log(`[apply] family=${family} values=${JSON.stringify(values)}`);
  const outcome = await applyRealConfig(s as any, family, values);
  console.log("[apply] outcome:", JSON.stringify(outcome, null, 2));
  await db.$disconnect();
})().catch((e) => {
  console.error("[apply] THREW:", e);
  process.exit(1);
});

