// Auto-forward the game's own port for NAT (non-dedicated-IP) servers ON
// THE PRIMARY — non-primary nodes already forwarded it above, since that
// was the only way to even perform the check. "Plug and play": every
// game server is reachable the moment it's handed to the customer
// instead of requiring a manual PortForward from the dashboard first.
// Found live: a real paying Minecraft customer with no dedicated IP and
// zero forwards had no path from any public IP to their game port at
// all. Dedicated IP servers need no forward — their guest port already
// IS the public port.
if (!SANDBOX && !dedicated && nodeRow?.isPrimary) {
  try {
    await allocateGameForward(server.nodeId, server.id, game.port, game.protocol);
    const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
    if (natErr) console.error(`[worker] game port forward sync failed for ${server.hostname}`, natErr);
  } catch (e) {
    // Never fail the whole provision over this — the server is still usable
    // via the dashboard's existing manual "Add forward" as a fallback.
    console.error(`[worker] auto-forward game port failed for ${server.hostname}`, e);
  }
}

// ...and the port the PLAYER actually connects to, which for eight families
// is not the one checked/forwarded above at all.
//
// `GAME_PORT` is a health-check map: where an image exposes a TCP port it
// prefers that one, because a TCP connect is real evidence the game process
// bound it. For rust/ark/projectzomboid/factorio/arkasa/soulmask/squad/kf2
// that port is RCON/query/admin and the join port is a different, UDP one —
// `GAME_PORT`'s own comments have always said so. Auto-forwarding "the
// game's own port" from that map therefore forwarded RCON and left the join
// port unreachable, on every NAT game server of those families ever
// provisioned. Found live 2026-09-06 on a fresh Rust provision: guest
// listening on both 28015/udp and 28016/tcp, exactly one game NAT rule
// (28016/tcp), and the dashboard showing the customer that RCON port as
// their connect address — no player could ever have joined.
//
// Deliberately additive: the health-check forward stays (a non-primary
// node's check runs THROUGH it, and removing it would break the retry
// path). Best-effort like the block above — never fail a provision over it.
const joinFam = gameFamilyForServer(server as unknown as ServerFamilyLike);
const join = joinFam ? joinPortFor(joinFam) : null;
if (!SANDBOX && !dedicated && join && (join.port !== game.port || join.protocol !== game.protocol)) {
  try {
    const already = await db.portForward.findFirst({
      where: { serverId: server.id, guestPort: join.port, protocol: join.protocol },
      select: { id: true },
    });
    if (!already) await allocateGameForward(server.nodeId, server.id, join.port, join.protocol);
    const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (join port)`);
    if (natErr) console.error(`[worker] join port forward sync failed for ${server.hostname}`, natErr);
  } catch (e) {
    console.error(`[worker] auto-forward join port failed for ${server.hostname}`, e);
  }
}

