const RUST_CONTAINER = "rust";
const RUST_IMAGE = "didstopia/rust-server";
/** Ports + volume exactly as prisma/catalog.ts's Rust template provisions them. */
const RUST_RUN_FLAGS = "-p 28015:28015/udp -p 28016:28016 -v /opt/rust:/steamcmd/rust --env-file /root/rust.env";

/**
 * Schema field key → the `didstopia/rust-server` env var that sets it.
 *
 * Read directly out of the image's own `/app/start.sh` on a real running
 * container (2026-09-06), not guessed — it builds the launch line with
 * `add_argument_pair ARGUMENTS "+server.hostname" "RUST_SERVER_NAME"` and
 * friends. `pve` has no env var of its own and goes through
 * `RUST_SERVER_STARTUP_ARGUMENTS` instead (see below).
 */
const RUST_ENV_MAP: Record<string, string> = {
  hostname: "RUST_SERVER_NAME",
  maxplayers: "RUST_SERVER_MAXPLAYERS",
  worldsize: "RUST_SERVER_WORLDSIZE",
  seed: "RUST_SERVER_SEED",
};

/** Replace `+convar <value>` in a Rust startup-argument string, or append it. */
function upsertConvarArg(args: string, convar: string, value: string): string {
  const re = new RegExp(`\\+${convar.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s+\\S+`);
  return re.test(args) ? args.replace(re, `+${convar} ${value}`) : `${args} +${convar} ${value}`.trim();
}

/**
 * Rust → container recreation with an --env-file (NOT server.cfg editing).
 *
 * Found live 2026-09-06 during the whole-catalog sweep, and it is the SAME class
 * of bug as Palworld's below. The previous version of this function looked for
 * `<identity>/cfg/server.cfg` and wrote convars into it. Two things were wrong,
 * both confirmed against a real running server rather than reasoned about:
 *
 *  1. **No server.cfg exists.** Rust does not ship one; the image creates
 *     `bans.cfg`, `users.cfg`, `serverauto.cfg` and `relay_cfg.json` in
 *     `/opt/rust/server/docker/cfg/` and nothing else. `remoteLocate` only ever
 *     matches an EXISTING file, so every apply soft-failed with "Could not
 *     locate Rust server.cfg". Honest, but nothing a customer could ever change.
 *  2. **Even creating one would not have worked.** `didstopia/rust-server` builds
 *     its entire launch line from `RUST_SERVER_*` environment variables
 *     (`/app/start.sh`), and those convars win. Proven directly: wrote
 *     `server.hostname "NXEON SWEEP TEST HOSTNAME"` + `server.maxplayers 42`
 *     into the real cfg dir, restarted, and RCON still reported
 *     `Hostname: Rust Server [DOCKER]`, `MaxPlayers: 500` — the env-var values.
 *     Fixing only the path would have shipped a function that writes a
 *     correct-looking file and changes nothing, which is the precise
 *     "reports success, nothing happened" failure this allowlist exists to stop.
 *
 * So, exactly like Palworld: the only durable way to change these settings is to
 * recreate the container with updated environment variables.
 */
async function applyRust(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  const envMap = await readContainerEnv(conn, RUST_CONTAINER);
  if (!envMap) {
    return { ok: false, applied: [], notes: [`Could not find the "${RUST_CONTAINER}" container — nothing was changed.`] };
  }

  const applied: string[] = [];
  const notes: string[] = [];
  for (const [key, val] of Object.entries(v)) {
    if (val == null) continue;
    const env = RUST_ENV_MAP[key];
    if (env) {
      envMap.set(env, String(val));
      applied.push(key);
    } else if (key === "pve") {
      // No RUST_SERVER_PVE exists. start.sh passes RUST_SERVER_STARTUP_ARGUMENTS
      // through verbatim ahead of the generated pairs, so it is the image's own
      // escape hatch for any convar it has no variable for.
      const args = envMap.get("RUST_SERVER_STARTUP_ARGUMENTS") ?? "-batchmode -load -nographics +server.secure 1";
      envMap.set("RUST_SERVER_STARTUP_ARGUMENTS", upsertConvarArg(args, "server.pve", bool(val)));
      applied.push(key);
    }
  }
  if (applied.length === 0) {
    return { ok: true, applied: [], notes: ["No changes to apply."] };
  }

  await writeEnvFile(conn, sftp, "/root/rust.env", envMap);

  const res = await recreateGameContainer(conn, {
    family: "rust",
    container: RUST_CONTAINER,
    runFlags: RUST_RUN_FLAGS,
    image: RUST_IMAGE,
  });
  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };

  if (v["worldsize"] != null || v["seed"] != null) {
    notes.push("World size / seed only take effect on a fresh map — the existing save is kept until the next wipe.");
  }
  notes.push(
    "Rust reloads its whole map on restart, so your server will be offline for several minutes before players can rejoin."
  );

  return { ok: true, applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`], notes };
}

