/**
 * The game port did not open within `GAME_PORT_CHECK_TIMEOUT_MS`. Decide whether
 * that means BROKEN or merely SLOW, by asking the guest whether it is still
 * doing work, and keep waiting for as long as it is.
 *
 * Why this exists: the 300s check cannot distinguish "Terraria is sitting on an
 * interactive world-selection prompt and will never bind a port" from "ARK is
 * 68% through a 22.9 GB SteamCMD download". Both look identical from outside —
 * SSH up, game port refused. Before this, both failed the order; measured on
 * 2026-09-06, every large Steam-based family was in the second group, so
 * healthy servers were being declared failed. Simply raising the timeout would
 * fix those at the cost of making genuinely dead servers waste 45 minutes of a
 * customer's time before admitting it.
 *
 * The progress signal is deliberately family-agnostic — no per-image knowledge
 * to drift out of date:
 *   - the guest's root filesystem is growing (a download/extract is running), OR
 *   - the game container has written to its log in the last sample window (world
 *     generation, engine startup — work that need not grow the disk much).
 * Either counts. `GAME_INSTALL_STALL_LIMIT` consecutive samples with neither is
 * what "stopped" means, so a brief pause between download and world-gen phases
 * does not end it prematurely.
 *
 * SAFETY: this runs ONLY after the normal check has already failed, so for every
 * family that provisions correctly today this code never executes at all. Any
 * error probing the guest returns `ok: false` immediately, i.e. exactly the
 * behaviour that existed before — this can only ever turn a failure into a
 * success, never the reverse, and `GAME_INSTALL_MAX_WAIT_MS` bounds it absolutely.
 */
async function waitOutGameInstall(
  server: { id: string; hostname: string; rootPassword: string | null; rootPasswordEnc?: string | null; sshPort: number | null; dedicatedIp?: { address: string } | null; node?: { publicIp: string } | null },
  checkHost: string,
  checkPort: number,
  protocol: "tcp" | "udp",
  step: (label: string) => Promise<unknown>
): Promise<{ ok: boolean; reason: string }> {
  const deadline = Date.now() + GAME_INSTALL_MAX_WAIT_MS;
  let lastUsedKb = -1;
  let stalls = 0;
  let samples = 0;

  // One SSH probe: root-fs used KB, plus how many bytes the game container has
  // logged recently. Both are plain reads; nothing is mutated on the guest.
  const probe = async (): Promise<{ usedKb: number; logBytes: number } | null> => {
    try {
      return await withServerSsh(server as any, async (conn) => {
        const r = await exec(
          conn,
          `used=$(df --output=used -k / 2>/dev/null | tail -1 | tr -d ' '); ` +
            `c=$(docker ps -q 2>/dev/null | head -1); ` +
            `lb=0; if [ -n "$c" ]; then lb=$(docker logs --since ${Math.round(GAME_INSTALL_SAMPLE_MS / 1000) + 10}s "$c" 2>&1 | wc -c); fi; ` +
            `echo "NXP:${"$"}{used:-0}:${"$"}{lb:-0}"`,
          QUICK_TIMEOUT_MS
        );
        const m = /NXP:(\d+):(\d+)/.exec(r.stdout);
        if (!m) return null;
        return { usedKb: Number(m[1]), logBytes: Number(m[2]) };
      });
    } catch {
      return null;
    }
  };

  await step("Installing the game — this one is a large download…");

  while (Date.now() < deadline) {
    const p = await probe();
    if (!p) {
      return { ok: false, reason: "Could not check whether the install was still running (the guest stopped answering)." };
    }
    samples++;
    if (lastUsedKb >= 0) {
      const grew = p.usedKb - lastUsedKb >= GAME_INSTALL_MIN_GROWTH_KB;
      const logging = p.logBytes > 0;
      if (grew || logging) {
        stalls = 0;
      } else if (++stalls >= GAME_INSTALL_STALL_LIMIT) {
        return {
          ok: false,
          reason:
            `The install stopped making progress (${stalls} consecutive minutes with no disk growth and no ` +
            `container output, at ${Math.round(p.usedKb / 1024)} MB used), so it was not simply still downloading.`,
        };
      }
    }
    lastUsedKb = p.usedKb;

    // Waiting and re-checking are the same operation: one sample window of port
    // attempts. Returns as soon as the port opens.
    const c = await checkGamePortOpen(checkHost, checkPort, protocol, {
      timeoutMs: GAME_INSTALL_SAMPLE_MS,
      intervalMs: GAME_PORT_CHECK_INTERVAL_MS,
    });
    if (c.ok) {
      return { ok: true, reason: `still installing for a further ~${samples} min, then the port opened` };
    }
  }
  return {
    ok: false,
    reason: `It was still installing after ${Math.round(GAME_INSTALL_MAX_WAIT_MS / 60_000)} minutes, which is longer than this platform waits.`,
  };
}

