test("installProgressed counts real disk growth as progress", () => {
  const prev = { usedKb: 1_000_000, logBytes: 0 };
  assert.equal(installProgressed(prev, { usedKb: 1_000_000 + GAME_INSTALL_MIN_GROWTH_KB, logBytes: 0 }), true);
