});

test("installProgressed counts container log output as progress even with a flat disk", () => {
  // World generation / engine startup writes little but logs plenty.
  assert.equal(installProgressed({ usedKb: 1_000_000, logBytes: 0 }, { usedKb: 1_000_000, logBytes: 2870 }), true);
});

test("installProgressed rejects a stalled install (no growth, no output)", () => {
  assert.equal(installProgressed({ usedKb: 1_000_000, logBytes: 0 }, { usedKb: 1_000_000, logBytes: 0 }), false);
  // Growth below the noise floor is not progress — ordinary log/tmp churn.
  assert.equal(installProgressed({ usedKb: 1_000_000, logBytes: 0 }, { usedKb: 1_000_050, logBytes: 0 }), false);
});

test("installProgressed never treats a SHRINKING disk as progress on its own", () => {
  assert.equal(installProgressed({ usedKb: 2_000_000, logBytes: 0 }, { usedKb: 1_000_000, logBytes: 0 }), false);
